"use client";

import { useEffect, useState } from "react";

import KpiCard from "@/components/kpis/KpiCard";

import {
  calculateKPIs,
  calculateMonthlyRevenue,
  calculateRevenueByCity,
  formatCurrency,
} from "@/lib/analytics";

import { 
  loadSales, 
  loadProperties 
} from "@/lib/data";

import type {
  KPIs,
  MonthlyRevenue,
  Property,
  RevenueByCity,
  Sale,
} from "@/lib/types";

import MonthlyRevenueChart from "@/components/charts/MonthlyRevenueChart";

export default function Home() {
  const [kpis, setKpis] = useState<KPIs | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [monthlyRevenue, setMonthlyRevenue] = useState<MonthlyRevenue[]>([]);
  const [
    revenueByCity,
    setRevenueByCity,
] = useState<RevenueByCity[]>([]);


  useEffect(() => {
    async function fetchData() {
      
      try {
        const [
          salesData,
          propertiesData,
        ] = await Promise.all([
          loadSales(),
          loadProperties(),
        ]);

        const calculatedKPIs =
          calculateKPIs(salesData);

        const calculatedMonthlyRevenue = calculateMonthlyRevenue(salesData);

        const calculatedRevenueByCity =
        calculateRevenueByCity(
          salesData,
          propertiesData
        );

        setKpis(calculatedKPIs);
        setMonthlyRevenue(calculatedMonthlyRevenue);
        setRevenueByCity(calculatedRevenueByCity);

      } catch (err) {
        console.error(err);

        if (err instanceof Error) {
          setError(err.message);
        } else {
          setError("Failed to load dashboard data.");
        }

      } finally {
        setLoading(false);
      }
    }

    

    fetchData();
  }, []);


  if (loading) {
    return (
      <main className="p-8">
        Loading dashboard...
      </main>
    );
  }


  if (error) {
    return (
      <main className="p-8">
        <p className="text-red-600">
          {error}
        </p>
      </main>
    );
  }


  if (!kpis) {
    return null;
  }


  return (
    <main className="min-h-screen bg-gray-50 px-6 py-8">
      <div className="mx-auto max-w-7xl">

        <header>
          <p className="text-sm font-medium text-gray-500">
            Real Estate Sales Analytics
          </p>

          <h1 className="mt-1 text-3xl font-bold tracking-tight text-gray-900">
            Desempeño Comercial
          </h1>

          <p className="mt-2 text-sm text-gray-500">
            Análisis de ingresos, eficiencia comercial
            y desempeño de ventas.
          </p>
        </header>


        <section className="mt-8 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">

          <KpiCard
            title="Ingreso Total"
            value={formatCurrency(
              kpis.totalRevenue
            )}
            subtitle="Ingresos acumulados"
          />

          <KpiCard
            title="Cantidad de Ventas"
            value={
              kpis.totalSales.toLocaleString()
            }
            subtitle="Operaciones realizadas"
          />

          <KpiCard
            title="Ticket Promedio"
            value={formatCurrency(
              kpis.averageTicket
            )}
            subtitle="Ingreso promedio por venta"
          />

          <KpiCard
            title="Comisión Total"
            value={formatCurrency(
              kpis.totalCommission
            )}
            subtitle="Comisiones generadas"
          />

        </section>

        <section className="mt-6">
          <MonthlyRevenueChart
            data={monthlyRevenue}
          />
        </section>

      </div>
    </main>
  );
}